pub fn edit(a: Str, b: Str) -> Int {
  let ca = a.chars()
  let cb = b.chars()
  let m = cb.len()
  var prev: List[Int] = range(0, m + 1)
  for i in range(1, ca.len() + 1) {
    let x = ca.get_or(i - 1, "")
    var row: List[Int] = [i]
    for j in range(1, m + 1) {
      let y = cb.get_or(j - 1, "")
      let subst_cost = match x == y {
        true => 0,
        false => 1,
      }
      let up = prev.get_or(j, 0) + 1
      let left = row.get_or(j - 1, 0) + 1
      let diag = prev.get_or(j - 1, 0) + subst_cost
      row = row.push(up.min(left).min(diag))
    }
    prev = row
  }
  return prev.get_or(m, 0)
}
